CREATE TABLE coord_lease_spans (workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,issue_id TEXT NOT NULL,session_id TEXT NOT NULL,principal_id TEXT NOT NULL,fencing_token INTEGER NOT NULL,claimed_at INTEGER NOT NULL,released_at INTEGER,release_reason TEXT,PRIMARY KEY(workspace_id,issue_id,fencing_token));
CREATE TABLE coord_file_claim_spans (workspace_id TEXT NOT NULL,project_id TEXT,repo TEXT NOT NULL,path TEXT NOT NULL,session_id TEXT NOT NULL,lease_issue_id TEXT,claimed_at INTEGER NOT NULL,released_at INTEGER,release_reason TEXT,PRIMARY KEY(workspace_id,repo,path,session_id,claimed_at));
CREATE TABLE coord_wip_denials (workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,issue_id TEXT NOT NULL,principal_id TEXT NOT NULL,occurred_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,project_id,issue_id,occurred_at,principal_id));
CREATE TRIGGER coord_freeze_lease_spans_insert BEFORE INSERT ON coord_lease_spans WHEN EXISTS(SELECT 1 FROM coord_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=NEW.project_id)) AND NOT EXISTS(SELECT 1 FROM coord_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=NEW.project_id)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER coord_freeze_lease_spans_update BEFORE UPDATE ON coord_lease_spans WHEN (EXISTS(SELECT 1 FROM coord_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=NEW.project_id)) AND NOT EXISTS(SELECT 1 FROM coord_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=NEW.project_id))) OR (EXISTS(SELECT 1 FROM coord_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=OLD.project_id)) AND NOT EXISTS(SELECT 1 FROM coord_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=OLD.project_id))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER coord_freeze_lease_spans_delete BEFORE DELETE ON coord_lease_spans WHEN EXISTS(SELECT 1 FROM coord_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=OLD.project_id)) AND NOT EXISTS(SELECT 1 FROM coord_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=OLD.project_id)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
